package br.com.conectatea.vinculo.infrastructure; import br.com.conectatea.vinculo.domain.TokenVinculo; import jakarta.persistence.LockModeType; import java.util.Optional; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface TokenVinculoRepository extends JpaRepository<TokenVinculo,Long>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select t from TokenVinculo t where t.codigoHash=:hash") Optional<TokenVinculo> findByHashForUpdate(@Param("hash")String hash);Optional<TokenVinculo> findByCodigoHash(String hash);}
